def max_len_sub(arr):
    n = len(arr)
    dp = [1] * n
    for i in range(1, n):
        for j in range(i):
            if arr[i] == arr[j]:
                dp[i] = dp[j] + 1
            else:
                dp[i] = max(dp[j], dp[i - 1])
    max_len = 0
    for i in range(n):
        max_len = max(max_len, dp[i])
    return max_len

