def get_Min_Squares(num):
    # Create a dictionary to store the number of squares for each number
    squares = {}
    for i in range(1, num+1):
        squares[i] = 0
        for j in range(i*i, num+1, i):
            squares[i] += 1

    # Initialize the minimum number of squares
    min_squares = float('inf')

    # Iterate over the numbers
    for i in range(1, num+1):
        # Check if the sum of the squares is equal to the given number
        if squares[i] == num:
            # If it is, update the minimum number of squares
            min_squares = min(min_squares, i)
        elif squares[i] > num:
            # If it is not, update the minimum number of squares
            min_squares = min(min_squares, get_Min_Squares(num-squares[i]))

    return min_squares

