def get_maxgold(matrix, n, m):
    # Initialize the matrix
    matrix = [[0 for x in range(m)] for x in range(n)]

    # Fill the matrix
    for i in range(n):
        for j in range(m):
            if i == 0 or j == 0:
                matrix[i][j] = 0
            elif i == 1 or j == 1:
                matrix[i][j] = 1
            else:
                matrix[i][j] = max(matrix[i-1][j], matrix[i][j-1])

    # Initialize the max gold
    max_gold = 0

    # Iterate through the matrix
    for i in range(n):
        for j in range(m):
            # Check if the current cell is a gold mine
            if matrix[i][j] == 1:
                # Check if the adjacent cells are also gold mines
                if i > 0 and matrix[i-1][j] == 1:
                    continue
                if j > 0 and matrix[i][j-1] == 1:
                    continue
                # Add the current cell to the max gold
                max_gold = max(max_gold, matrix[i][j] + 1)

    return max_gold

