def binomial_probability(n, k, p):
    if n < k:
        return 0
    if n == k:
        return 1
    if n == 0:
        return 1
    if k == 0:
        return 1
    if n == k:
        return p**k
    else:
        return binomial_probability(n-1, k-1, p) + binomial_probability(n-1, k, p**2)

