def add_consecutive_nums(nums):
    result = []
    for i in range(len(nums)):
        if i == 0 or i == len(nums) - 1:
            continue
        if nums[i] == nums[i - 1]:
            continue
        if nums[i] == nums[i - 1] + nums[i - 2]:
            result.append(nums[i])
    return result

